  "arrays-practice": {
    "c": "#include <stdio.h>\n\nint find(const int values[], size_t count, int target) {\n    for (size_t i = 0; i < count; ++i) if (values[i] == target) return (int)i;\n    return -1;\n}\nint main(void) {\n    int values[] = {4, 8, 12, 16, 20};\n    int requested[] = {12, 7};\n    for (size_t test = 0; test < 2; ++test) {\n        int index = find(values, 5, requested[test]);\n        if (index >= 0) printf(\"%d: index %d\\n\", requested[test], index);\n        else printf(\"%d: not found\\n\", requested[test]);\n    }\n    return 0;\n}\n",
    "cpp": "#include <iostream>\n\nint find(const int values[], int count, int target) {\n    for (int i = 0; i < count; ++i) if (values[i] == target) return i;\n    return -1;\n}\nint main() {\n    int values[] = {4, 8, 12, 16, 20};\n    for (int requested : {12, 7}) {\n        int index = find(values, 5, requested);\n        if (index >= 0) std::cout << requested << \": index \" << index << \"\\n\";\n        else std::cout << requested << \": not found\\n\";\n    }\n    return 0;\n}\n",
    "python": "def find(values, target):\n    for i, value in enumerate(values):\n        if value == target:\n            return i\n    return -1\n\nvalues = [4, 8, 12, 16, 20]\nfor requested in [12, 7]:\n    index = find(values, requested)\n    print(f\"{requested}: index {index}\" if index >= 0 else f\"{requested}: not found\")\n",
    "java": "\npublic class Main {\n    static int find(int[] values, int target) {\n        for (int i = 0; i < values.length; ++i) if (values[i] == target) return i;\n        return -1;\n    }\n    public static void main(String[] args) {\n        int[] values = {4, 8, 12, 16, 20};\n        for (int requested : new int[] {12, 7}) {\n            int index = find(values, requested);\n            System.out.println(requested + (index >= 0 ? \": index \" + index : \": not found\"));\n        }\n    }\n}\n",
    "javascript": "'use strict';\nfunction find(values, target) {\n    for (let i = 0; i < values.length; ++i) if (values[i] === target) return i;\n    return -1;\n}\n\nconst values = [4, 8, 12, 16, 20];\nfor (const requested of [12, 7]) {\n    const index = find(values, requested);\n    console.log(index >= 0 ? `${requested}: index ${index}` : `${requested}: not found`);\n}\n",
    "csharp": "using System;\n\nclass Program {\n    static int Find(int[] values, int target) {\n        for (int i = 0; i < values.Length; ++i) if (values[i] == target) return i;\n        return -1;\n    }\n    static void Main() {\n        int[] values = {4, 8, 12, 16, 20};\n        foreach (int requested in new int[] {12, 7}) {\n            int index = Find(values, requested);\n            Console.WriteLine(index >= 0 ? $\"{requested}: index {index}\" : $\"{requested}: not found\");\n        }\n    }\n}\n"
  },
