    "c": "#include <stdio.h>\n\nvoid update(int *score) { if (score != NULL) *score = 100; }\nint main(void) {\n    int score = 20;\n    update(&score);\n    printf(\"Score: %d\\n\", score);\n    return 0;\n}\n",
    "cpp": "#include <iostream>\n\nvoid update(int& score) { score = 100; }\nint main() {\n    int score = 20;\n    update(score);\n    std::cout << \"Score: \" << score << \"\\n\";\n    return 0;\n}\n",
    "python": "# Python passes object references by assignment; mutate the shared dictionary.\ndef update(score):\n    score[\"value\"] = 100\n\nscore = {\"value\": 20}\nupdate(score)\nprint(f\"Score: {score['value']}\")\n",
    "java": "\npublic class Main {\n    // Java passes a copy of the reference by value; the object is shared.\n    static class Score { int value; Score(int value) { this.value = value; } }\n    static void update(Score score) { score.value = 100; }\n    public static void main(String[] args) {\n        Score score = new Score(20);\n        update(score);\n        System.out.println(\"Score: \" + score.value);\n    }\n}\n",
    "javascript": "'use strict';\n// JavaScript passes the reference value by value; mutate the shared object.\nfunction update(score) { score.value = 100; }\n\nconst score = { value: 20 };\nupdate(score);\nconsole.log(`Score: ${score.value}`);\n",
