  "pointers-5": {
    "c": "#include <stdio.h>\n#include <stdlib.h>\n\n\nint main(void) {\n    size_t count = 3;\n    int *values = malloc(count * sizeof *values);\n    if (values == NULL) {\n        fputs(\"Allocation failed\\n\", stderr);\n        return 1;\n    }\n    int total = 0;\n    for (size_t i = 0; i < count; ++i) {\n        values[i] = (int)(i + 1) * 10;\n        total += values[i];\n    }\n    printf(\"Sum: %d\\n\", total);\n    free(values); /* Exactly one release on the successful path. */\n    values = NULL;\n    return 0;\n}\n",
    "cpp": "#include <iostream>\n#include <memory>\n#include <new>\n\n\nint main() {\n    // RAII owns the dynamic array and deletes it once when its owner leaves scope.\n    try {\n        auto values = std::make_unique<int[]>(3);\n        int total = 0;\n        for (int i = 0; i < 3; ++i) { values[i] = (i + 1) * 10; total += values[i]; }\n        std::cout << \"Sum: \" << total << \"\\n\";\n    } catch (const std::bad_alloc&) {\n        std::cerr << \"Allocation failed\\n\";\n        return 1;\n    }\n    return 0;\n}\n",
    "python": "# List memory is managed automatically: do not call C malloc/free.\nvalues = [0] * 3\ntotal = 0\nfor i in range(len(values)):\n    values[i] = (i + 1) * 10\n    total += values[i]\nprint(f\"Sum: {total}\")\n",
    "java": "\npublic class Main {\n    \n    public static void main(String[] args) {\n        // Managed array allocation: garbage collection releases unreachable memory.\n        int[] values = new int[3];\n        int total = 0;\n        for (int i = 0; i < values.length; ++i) { values[i] = (i + 1) * 10; total += values[i]; }\n        System.out.println(\"Sum: \" + total);\n    }\n}\n",
    "javascript": "'use strict';\n// Managed array allocation; the garbage collector owns memory reclamation.\nconst values = new Array(3);\nlet total = 0;\nfor (let i = 0; i < values.length; ++i) { values[i] = (i + 1) * 10; total += values[i]; }\nconsole.log(`Sum: ${total}`);\n",
    "csharp": "using System;\n\nclass Program {\n    \n    static void Main() {\n        // Managed array allocation: no unsafe pointers or explicit free are needed.\n        int[] values = new int[3];\n        int total = 0;\n        for (int i = 0; i < values.Length; ++i) { values[i] = (i + 1) * 10; total += values[i]; }\n        Console.WriteLine($\"Sum: {total}\");\n    }\n}\n"
  },
