    "python": "# Rebind a reference to a second shared object; this is not a raw pointer.\nfirst, second = {\"value\": 10}, {\"value\": 20}\nreference = first\nprint(f\"First target: {reference['value']}\")\nreference = second\nreference[\"value\"] = 99\nprint(f\"First: {first['value']}\\nSecond: {second['value']}\")\n",
