    "c": "#include <stdio.h>\n#include <stdbool.h>\n/* C has no classes or access modifiers; structs and functions model the interface. */\ntypedef struct { int balance; } BankAccount;\nstatic BankAccount makeAccount(int balance) { return (BankAccount){balance}; }\nstatic void deposit(BankAccount *account, int amount) {\n    if (amount > 0) account->balance += amount;\n}\nstatic int getBalance(const BankAccount *account) { return account->balance; }\n\nint main(void) {\n    BankAccount first = makeAccount(100);\n    deposit(&first, 25);\n    printf(\"Balance: %d\\n\", getBalance(&first));\n    return 0;\n}\n",
    "cpp": "#include <iostream>\n#include <string>\nclass BankAccount {\n    int balance;\npublic:\n    explicit BankAccount(int initial) : balance(initial) {}\n    void deposit(int amount) { if (amount > 0) balance += amount; }\n    int getBalance() const { return balance; }\n};\n\nint main() {\n    BankAccount first(100);\n    first.deposit(25);\n    std::cout << \"Balance: \" << first.getBalance() << \"\\n\";\n}\n",
    "python": "class BankAccount:\n    # Name mangling discourages direct access; it is not compiler-enforced privacy.\n    def __init__(self, initial):\n        self.__balance = initial\n    def deposit(self, amount):\n        if amount > 0:\n            self.__balance += amount\n    def get_balance(self):\n        return self.__balance\n\nfirst = BankAccount(100)\nfirst.deposit(25)\nprint(f\"Balance: {first.get_balance()}\")\n",
    "java": "public class Main {\n    static class BankAccount {\n        private int balance;\n        BankAccount(int initial) { balance = initial; }\n        void deposit(int amount) { if (amount > 0) balance += amount; }\n        int getBalance() { return balance; }\n    }\n\n    public static void main(String[] args) {\n        BankAccount first = new BankAccount(100);\n        first.deposit(25);\n        System.out.println(\"Balance: \" + first.getBalance());\n    }\n}\n",
