    "csharp": "using System;\nclass Program {\n    class BankAccount {\n        private int balance;\n        public BankAccount(int initial) { balance = initial; }\n        public void Deposit(int amount) { if (amount > 0) balance += amount; }\n        public int GetBalance() { return balance; }\n    }\n\n    static void Main() {\n        BankAccount first = new BankAccount(100);\n        first.Deposit(25);\n        Console.WriteLine(\"Balance: \" + first.GetBalance());\n    }\n}\n"
