    "c": "#include <stdio.h>\n#include <stdbool.h>\n/* C has no classes or access modifiers; structs and functions model the interface. */\n/* C models reuse through composition, not class inheritance. */\ntypedef struct { const char *name; } Animal;\ntypedef struct { Animal animal; } Dog;\n\nint main(void) {\n    Dog dog = {{\"Milo\"}};\n    printf(\"Animal: %s\\n\", dog.animal.name);\n    return 0;\n}\n",
    "cpp": "#include <iostream>\n#include <string>\nclass Animal { public: std::string name; explicit Animal(std::string text) : name(text) {} };\nclass Dog : public Animal { public: explicit Dog(std::string text) : Animal(text) {} };\n\nint main() {\n    Dog dog(\"Milo\"); std::cout << \"Animal: \" << dog.name << \"\\n\";\n}\n",
    "python": "class Animal:\n    def __init__(self, name):\n        self.name = name\nclass Dog(Animal):\n    pass\n\ndog = Dog(\"Milo\")\nprint(\"Animal: \" + dog.name)\n",
    "java": "public class Main {\n    static class Animal { String name; Animal(String name) { this.name = name; } }\n    static class Dog extends Animal { Dog(String name) { super(name); } }\n\n    public static void main(String[] args) {\n        Dog dog = new Dog(\"Milo\"); System.out.println(\"Animal: \" + dog.name);\n    }\n}\n",
