  "oop-6": {
    "c": "#include <stdio.h>\n#include <stdbool.h>\n/* C has no classes or access modifiers; structs and functions model the interface. */\ntypedef struct { void (*speak)(void); } Animal;\nstatic void dogSpeak(void) { puts(\"Woof\"); }\nstatic void catSpeak(void) { puts(\"Meow\"); }\n\nint main(void) {\n    Animal animals[] = {{dogSpeak}, {catSpeak}};\n    for (size_t i = 0; i < 2; ++i) animals[i].speak();\n    return 0;\n}\n",
    "cpp": "#include <iostream>\n#include <string>\nclass Animal { public: virtual void speak() const = 0; virtual ~Animal() = default; };\nclass Dog : public Animal { public: void speak() const override { std::cout << \"Woof\\n\"; } };\nclass Cat : public Animal { public: void speak() const override { std::cout << \"Meow\\n\"; } };\n\nint main() {\n    Dog dog; Cat cat;\n    const Animal *animals[] = {&dog, &cat};\n    for (const Animal *animal : animals) animal->speak();\n}\n",
    "python": "class Animal:\n    def speak(self):\n        raise NotImplementedError\nclass Dog(Animal):\n    def speak(self):\n        print(\"Woof\")\nclass Cat(Animal):\n    def speak(self):\n        print(\"Meow\")\n\nfor animal in [Dog(), Cat()]:\n    animal.speak()\n",
    "java": "public class Main {\n    interface Animal { void speak(); }\n    static class Dog implements Animal { public void speak() { System.out.println(\"Woof\"); } }\n    static class Cat implements Animal { public void speak() { System.out.println(\"Meow\"); } }\n\n    public static void main(String[] args) {\n        Animal[] animals = {new Dog(), new Cat()};\n        for (Animal animal : animals) animal.speak();\n    }\n}\n",
    "javascript": "class Animal { speak() { throw new Error(\"Implement speak\"); } }\nclass Dog extends Animal { speak() { console.log(\"Woof\"); } }\nclass Cat extends Animal { speak() { console.log(\"Meow\"); } }\n\nfor (const animal of [new Dog(), new Cat()]) animal.speak();\n",
    "csharp": "using System;\nclass Program {\n    interface IAnimal { void Speak(); }\n    class Dog : IAnimal { public void Speak() { Console.WriteLine(\"Woof\"); } }\n    class Cat : IAnimal { public void Speak() { Console.WriteLine(\"Meow\"); } }\n\n    static void Main() {\n        IAnimal[] animals = {new Dog(), new Cat()};\n        foreach (IAnimal animal in animals) animal.Speak();\n    }\n}\n"
  },
