    "c": "#include <stdio.h>\n#include <stdbool.h>\n/* C has no classes or access modifiers; structs and functions model the interface. */\n/* C has no protected modifier; composition and an accessor model the operation. */\ntypedef struct { int score; } Base;\ntypedef struct { Base base; } Derived;\nstatic int readScore(const Derived *object) { return object->base.score; }\n\nint main(void) {\n    Derived object = {{42}};\n    printf(\"Score: %d\\n\", readScore(&object));\n    return 0;\n}\n",
    "cpp": "#include <iostream>\n#include <string>\nclass Base { protected: int score = 42; };\nclass Derived : public Base { public: int readScore() const { return score; } };\n\nint main() {\n    Derived object; std::cout << \"Score: \" << object.readScore() << \"\\n\";\n}\n",
    "python": "class Base:\n    # Python has no enforced protected access; this is a convention.\n    def __init__(self):\n        self._score = 42\nclass Derived(Base):\n    def read_score(self):\n        return self._score\n\nprint(f\"Score: {Derived().read_score()}\")\n",
    "java": "public class Main {\n    static class Base { protected int score = 42; }\n    static class Derived extends Base { int readScore() { return score; } }\n\n    public static void main(String[] args) {\n        System.out.println(\"Score: \" + new Derived().readScore());\n    }\n}\n",
    "javascript": "// JavaScript has no protected access modifier; an underscore is a convention.\nclass Base { constructor() { this._score = 42; } }\nclass Derived extends Base { readScore() { return this._score; } }\n\nconsole.log(\"Score: \" + new Derived().readScore());\n",
