    "javascript": "'use strict';\nconst assert = require('node:assert/strict');\nfunction doubleValue(n) { return n * 2; }\nassert.equal(doubleValue(6), 12); console.log(\"doubles six: pass\");\n",
    "csharp": "using System;\nclass Program {\n    static void Require(bool condition, string name) { if (!condition) throw new Exception(\"FAIL: \" + name); }\n    static int DoubleValue(int n) { return n * 2; }\n    static void Main() {\n        Require(DoubleValue(6) == 12, \"doubles six\"); Console.WriteLine(\"doubles six: pass\");\n    }\n}\n"
